import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1199, own='cte_122.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

H("830.d.1.A",3,"A student compares job listings and notices that plants increasingly hire people who can program robots and read sensor data. This observation describes a:","trend in manufacturing careers toward automation skills",["decline in all technical jobs","rule that factories hire only artists","ban on training programs"],"Careers shift toward technology skills.")
H("830.d.1.A",4,"Which source would give the most reliable data on how many manufacturing jobs a region expects to add over the next decade?","a labor market projection report from a state workforce agency",["a classmate's guess","an old yearbook","a product advertisement"],"Use labor market data.")
H("830.d.1.B",3,"A line worker lifts 40-pound cartons from the floor all shift and develops back pain. Adjusting the work height with a lift table addresses which kind of issue?","an ergonomic issue",["a pricing issue","a marketing issue","a payroll issue"],"Ergonomics fits work to the body.")
H("830.d.1.B",4,"Solvent vapors in a poorly ventilated assembly bay raise a worry about breathing hazards. This is mainly a:","health and environmental concern needing ventilation or substitution",["scheduling concern only","color-matching concern","packaging concern"],"Ventilation controls vapor exposure.")
H("830.d.2.A",3,"A small piston pushes on enclosed oil, and the pressure is felt equally throughout the fluid and moves a much larger piston. This behavior is explained by:","Pascal's Law",["Ohm's Law","Newton's cradle","Murphy's Law"],"Pressure transmits equally in an enclosed fluid.")
H("830.d.2.A",4,"A 2 square inch piston is pushed with 100 pounds. The pressure created in the sealed fluid is:","50 psi",["200 psi","102 psi","98 psi"],"100 ÷ 2 = 50 psi.")
H("830.d.2.B",3,"In a hydraulic press, the component that turns fluid pressure into the straight-line push on the ram is the:","cylinder actuator",["reservoir cap","filter element","pressure gauge"],"Actuators convert fluid power to motion.")
H("830.d.2.B",4,"Which choice lists only actuators?","a hydraulic cylinder and a hydraulic motor",["a reservoir and a filter","a gauge and a hose","a strainer and a tank"],"Cylinders and motors do work.")
H("830.d.2.C",3,"A technician needs a part that opens and closes passages to steer oil toward either end of a cylinder. She chooses a:","directional control valve",["suction strainer","breather cap","sight glass"],"Directional valves route flow.")
H("830.d.2.C",4,"A valve that limits the highest pressure in a hydraulic system by opening to the tank is a:","relief valve",["check valve","needle gauge","flow meter"],"Relief valves cap pressure.")
H("830.d.2.D",3,"If a cylinder's piston area is doubled and the pressure stays the same, the force it can push with:","doubles",["halves","stays the same","drops to zero"],"Force = pressure × area.")
H("830.d.2.D",4,"A cylinder needs more oil to travel its full stroke when the bore is larger because the cylinder volume:","increases with piston area times stroke length",["depends only on paint color","decreases as bore grows","is unrelated to size"],"Volume = area × stroke.")
H("830.d.2.E",3,"A sealed tank of compressed air is left in a hot sun and its pressure climbs as the temperature rises at constant volume. This follows:","Gay-Lussac's Law",["Boyle's Law","Pascal's cradle","Ohm's Law"],"Pressure rises with temperature at fixed volume.")
H("830.d.2.E",4,"A pneumatic cylinder squeezes air into half its original volume at constant temperature, and the pressure roughly doubles. This follows:","Boyle's Law",["Charles's Law","Gay-Lussac's Law","Newton's Law"],"Pressure and volume are inversely related.")
H("830.d.2.F",3,"A pump motor adds energy to the oil, the oil moves the cylinder, and some energy leaves as heat. This shows that energy in a system is:","transformed rather than created or destroyed",["created by the pump","lost completely","destroyed by valves"],"Energy is conserved.")
H("830.d.2.F",4,"In a fluid power system, why does the oil get warm even though the pump only moves fluid?","some input energy converts to heat through friction and throttling",["oil makes its own heat","heat is a type of pressure","the tank adds energy"],"Losses show up as heat.")
H("830.d.2.G",3,"Pressure in a hydraulic circuit builds when:","the pump flow meets resistance from the load",["the tank is empty","the pump runs with no restriction","the oil is removed"],"Pumps make flow; resistance creates pressure.")
H("830.d.2.G",4,"A hydraulic pump running with its outlet open to the tank at idle shows nearly zero pressure because:","there is almost no resistance to flow",["the pump is broken","oil has no weight","gauges never read tank lines"],"No resistance, no pressure.")
H("830.d.2.H",3,"A rubber seal that hardens and cracks when a system runs far hotter than its rating will most likely:","leak and allow fluid contamination",["seal better","change oil color only","reduce noise"],"Heat degrades seals.")
H("830.d.2.H",4,"Choosing a seal compound that is compatible with the fluid and operating temperature range matters because the wrong material can:","swell, harden or break down and fail",["improve cooling","increase pump speed","remove the need for filters"],"Match seals to conditions.")
H("830.d.2.I",3,"The lowest temperature at which an oil gives off enough vapor to briefly flash when a flame passes is its:","flash point",["fire point","pour point","boiling point"],"Flash point is the first brief ignition.")
H("830.d.2.I",4,"Which statement is correct about fire point and auto-ignition temperature?","fire point needs a flame to sustain burning, while auto-ignition occurs with no outside flame",["they are always identical","fire point needs no flame","auto-ignition needs a spark"],"Auto-ignition is spontaneous.")
H("830.d.2.J",3,"A pump moves 5 cubic inches of oil each time its shaft turns once. That 5 cubic inches per revolution is the pump's:","displacement",["viscosity","pour point","back pressure"],"Displacement is volume per revolution.")
H("830.d.2.J",4,"A pump with a displacement of 2 cubic inches per revolution turns 1,000 rpm. Its ideal flow is about:","2,000 cubic inches per minute",["500 cubic inches per minute","1,002 cubic inches per minute","20 cubic inches per minute"],"2 × 1000 = 2000.")
H("830.d.2.K",3,"A pinhole leak in a pressurized hydraulic hose sprays a fine stream. The hazard of touching it with a bare hand is:","high-pressure fluid injection under the skin",["a mild rash only","sunburn","a loose tooth"],"Injection injuries are serious.")
H("830.d.2.K",4,"A technician searches for a hydraulic leak by running a piece of cardboard near the hose instead of her hand because:","a fine jet can pierce skin and requires emergency treatment",["cardboard makes the leak smaller","hands are too clean","cardboard repairs hoses"],"Never use hands to find leaks.")
H("830.d.3.A",3,"On a schematic, a circle with a triangle pointing outward and a straight line attached is the symbol for a:","pump",["cylinder","filter","check valve"],"Pump symbol has an outward triangle.")
H("830.d.3.A",4,"A rectangle with a rod symbol on one side and a piston inside most likely represents a:","cylinder",["reservoir","motor","accumulator"],"Cylinders show a piston and rod.")
H("830.d.3.B",3,"A drawing that uses simple standard symbols to show how components connect, not what they look like, is a:","schematic diagram",["pictorial diagram","product photo","floor plan"],"Schematics use symbols.")
H("830.d.3.B",4,"A pictorial diagram differs from a schematic because it:","shows the actual appearance and placement of components",["uses only symbols","never shows hoses","lists no parts"],"Pictorials show how parts look.")
H("830.d.3.C",3,"A technician matches a diamond-shaped schematic box with arrows to a valve body on the bench. She is:","matching a schematic symbol to a physical component",["painting a valve","ordering oil","drawing a pump"],"Symbol-to-part matching.")
H("830.d.3.C",4,"On the bench, a part with two ports and a ball inside that only passes flow one way matches which schematic symbol?","a check valve symbol",["a cylinder symbol","a motor symbol","a tank symbol"],"One-way flow means check valve.")
H("830.d.3.D",3,"Following a schematic, a student connects a pump, a directional valve and a cylinder so that shifting the valve extends and retracts the rod. She is:","constructing and operating a basic circuit",["testing a bearing","tuning a chain","cleaning a tank"],"Build the circuit from the schematic.")
H("830.d.3.D",4,"Before powering a circuit built from a schematic, the student should first:","verify connections against the schematic and check that the relief valve is set low",["bypass the relief valve","run at full pressure","remove the filter"],"Verify and set safe pressure.")
H("830.d.3.E",3,"A technician looks at a lift gate with a cylinder and writes a drawing using standard symbols for the pump, valve, cylinder and tank. She is:","drawing a fluid power schematic from an application",["editing a payroll form","painting a gate","measuring a weld"],"Draw from the real system.")
H("830.d.3.E",4,"When drawing a schematic for a simple clamp, the reservoir symbol should connect to the pump inlet and:","to the return line of the directional valve",["to the clamp jaw only","to a power outlet","to nothing"],"Return flow goes to tank.")
H("830.d.4.A",3,"A gauge at the pump outlet reads normal, but the gauge at the cylinder reads far lower. A likely cause is:","a leak or restriction between the two gauge points",["a gauge painted wrong","a full tank","a longer hose label"],"Pressure drop shows loss.")
H("830.d.4.A",4,"A cylinder that drifts slowly down under load with no external leak visible most likely has:","an internal leak past the piston seal",["too much oil in the tank","a clean breather","a bright gauge"],"Internal leaks cause drift.")
H("830.d.4.B",3,"A flow meter reads half of the pump's rated flow while the cylinder moves very slowly. The meter helps the technician spot:","improper flow caused by a restriction or worn pump",["a paint problem","a label problem","a wrong tool color"],"Flow readings reveal faults.")
H("830.d.4.B",4,"If a flow meter shows normal flow but the cylinder is still slow under load, the technician should suspect:","internal leakage in the cylinder or valve",["a perfect system","a high tank level","a bad nameplate"],"Normal supply but low output points to bypass.")
H("830.d.4.C",3,"The temperature gauge on a hydraulic tank climbs steadily to 190 degrees Fahrenheit during a shift. This suggests the system is:","overheating, perhaps from a stuck relief valve or low oil",["running cold","operating perfectly","overfilled with air"],"Heat signals wasted energy.")
H("830.d.4.C",4,"Oil that stays too hot for long periods will most likely:","thin out, oxidize and shorten seal and fluid life",["thicken forever","last longer","cool the pump"],"Heat damages oil and seals.")
H("830.d.4.D",3,"A shop uses oil to lift a heavy press and also uses compressed air to blow chips off parts. Which statement correctly compares the two?","hydraulics use liquid that barely compresses; pneumatics use air that compresses",["both use gas","hydraulics use air only","pneumatics use oil only"],"Liquids vs gases.")
H("830.d.4.D",4,"Why does a pneumatic cylinder feel springy under load compared with a hydraulic cylinder?","air compresses, but oil barely does",["oil is lighter","air is a solid","cylinders differ in color"],"Compressibility difference.")
H("830.d.4.E",3,"An air dryer is installed after the compressor so that water vapor in the air is removed before it reaches valves. This prevents:","moisture damage and rust in the pneumatic components",["a loss of paint","a change in tag shape","an increase in wire size"],"Dryers protect components.")
H("830.d.4.E",4,"Water in the lines of an outdoor plant freezes in winter. A dryer helps prevent:","frozen lines and blocked air flow",["warmer air","looser bolts","brighter lights"],"Dry air won't freeze up.")
H("830.d.4.F",3,"A small unit adds a fine oil mist to the compressed air before it reaches an air tool. This lubrication reduces:","wear and friction on moving parts",["air pressure to zero","tool size","hose length"],"Lubrication cuts wear.")
H("830.d.4.F",4,"A pneumatic cylinder starts to stick and squeal. Adding lubricator oil in the air line helps because it:","reduces friction on seals and rod surfaces",["adds more air","removes the cylinder","heats the line"],"Lubricate to cut friction.")
H("830.d.5.A",3,"A system's pressure is 1,000 psi and the piston area is 4 square inches. The force the cylinder can push with is:","4,000 pounds",["250 pounds","1,004 pounds","996 pounds"],"F = P × A.")
H("830.d.5.A",4,"If the same pressure acts on a piston with only 50% of its original area, the output force:","drops to half",["doubles","stays the same","becomes infinite"],"Force depends on area.")
H("830.d.5.B",3,"A pump supplies 10 gallons per minute to a cylinder. The rod moves faster when the:","bore diameter is smaller for the same flow",["bore diameter is larger","flow is reduced to zero","tank is larger"],"Speed = flow ÷ area.")
H("830.d.5.B",4,"A cylinder has a 3 square inch piston and receives 231 cubic inches of oil per minute. The rod speed is about:","77 inches per minute",["693 inches per minute","3 inches per minute","231 inches per minute"],"231 ÷ 3 = 77.")
H("830.d.5.C",3,"If the load on a cylinder increases while flow stays the same, the system pressure:","rises to push the heavier load",["falls to zero","stays unrelated","becomes a vacuum"],"Heavier loads need more pressure.")
H("830.d.5.C",4,"A cylinder with a 2 square inch piston must push 3,000 pounds. The needed pressure is:","1,500 psi",["6,000 psi","3,002 psi","750 psi"],"3000 ÷ 2 = 1500.")
H("830.d.5.D",3,"If more oil volume per minute is sent to the same cylinder, the rod moves:","faster",["slower","backward only","not at all"],"More flow, more speed.")
H("830.d.5.D",4,"Doubling both the flow rate and the piston area, the rod speed will:","stay about the same",["double","quadruple","drop to zero"],"Speed = flow ÷ area.")
H("830.d.5.E",3,"A cylinder with a 5 square inch piston is supplied 800 psi. Using Pascal's Law, the extending force is:","4,000 pounds",["160 pounds","805 pounds","795 pounds"],"800 × 5 = 4000.")
H("830.d.5.E",4,"To lift a 12,000 pound load with a 6 square inch piston, the pressure needed is:","2,000 psi",["72,000 psi","18 psi","200 psi"],"12000 ÷ 6 = 2000.")
H("830.d.6.A",3,"A student compares the machine that squeezes atmospheric air into a storage tank with the machine that pushes oil through hoses. The first is a compressor and the second is a:","hydraulic pump",["relief valve","filter","gauge"],"Compressors move air; pumps move oil.")
H("830.d.6.A",4,"Which difference is correct?","a compressor raises the pressure of a gas; a hydraulic pump moves a nearly incompressible liquid",["both move solids","a compressor moves oil","a pump moves only air"],"Gas versus liquid.")
H("830.d.6.B",3,"Oil returning from the circuit sits in the tank, where heat dissipates and air bubbles and dirt settle out. These are functions of the hydraulic:","reservoir",["accumulator","actuator","strainer"],"Reservoirs store, cool and settle fluid.")
H("830.d.6.B",4,"A reservoir baffle plate separates the return line from the pump suction so that:","bubbles and contaminants can settle before oil is pumped again",["oil never cools","oil never moves","air enters the pump"],"Baffles improve settling.")
H("830.d.6.C",3,"A pump with two meshing toothed wheels that carry oil around the housing is a:","gear pump",["vane pump","diaphragm pump","piston pump"],"Gear pumps use meshing gears.")
H("830.d.6.C",4,"A pump with sliding blades in a slotted rotor that spins inside an offset ring is a:","vane pump",["gear pump","piston pump","fan"],"Vane pumps use sliding vanes.")
H("830.d.6.D",3,"A pump that moves the same volume every revolution unless the speed changes is a:","fixed displacement pump",["variable displacement pump","vacuum pump","bladder pump"],"Fixed means constant volume per turn.")
H("830.d.6.D",4,"A pump whose swash plate angle can be changed to vary flow at constant speed is a:","variable displacement pump",["fixed displacement gear pump","hand pump","manual jack"],"Variable displacement changes output.")
H("830.d.6.E",3,"The device that turns hydraulic power into useful work such as pushing, pulling or turning is the:","actuator",["tank","strainer","gauge"],"Actuators do the work.")
H("830.d.6.E",4,"If the actuator is removed from a circuit, the oil would have:","no way to produce useful motion or force",["more work to do","no pressure at all times","a larger pump"],"Without actuators there is no output.")
H("830.d.6.F",3,"A technician mounts a dial that reads system pressure and a meter that reads oil flow rate. Together they help:","monitor how the system is performing",["decorate the circuit","slow the pump","hide leaks"],"Gauges and meters monitor.")
H("830.d.6.F",4,"A pressure gauge on a hydraulic power unit lets an operator confirm that the:","system is operating at the correct pressure",["tank is painted","oil is blue","hoses are new"],"Pressure gauges show operating pressure.")
H("830.d.6.G",3,"A hydraulic valve that sets the highest allowed pressure and dumps extra flow back to the tank is a:","relief valve",["flow meter","check valve","sight glass"],"Relief valves cap pressure.")
H("830.d.6.G",4,"A valve that lowers pressure in one branch of a circuit below the main system pressure is a:","pressure reducing valve",["relief valve at tank","check valve","filter"],"Reducing valves lower branch pressure.")
H("830.d.6.H",3,"On a compressed air line, a device that holds downstream pressure at a steady lower value is a:","regulator",["compressor","dryer","filter"],"Regulators set downstream pressure.")
H("830.d.6.H",4,"A small valve on an air receiver that opens to vent air if tank pressure goes too high is a:","safety relief valve",["needle valve","regulator gauge","muffler"],"Safety valves protect tanks.")
H("830.d.6.I",3,"A needle valve in a hydraulic line is turned in to slow a cylinder's travel. This valve is a:","flow control valve",["pressure gauge","shut-off tank","pump"],"Flow controls set speed.")
H("830.d.6.I",4,"Closing down a flow control valve in series with a cylinder will:","reduce the actuator speed",["increase speed","raise voltage","remove pressure"],"Less flow means slower speed.")
H("830.d.6.J",3,"A hydraulic motor that turns only one direction when oil flows through it in one way is a:","unidirectional motor",["bidirectional motor","linear cylinder","accumulator"],"Single-direction rotation.")
H("830.d.6.J",4,"A motor that can turn clockwise or counterclockwise depending on which port gets oil is a:","bidirectional motor",["unidirectional motor","check valve","gauge"],"Reversible rotation.")
H("830.d.6.K",3,"Compressed air pushes on a piston to lift a part on an assembly line, and a hydraulic motor turns a conveyor. Both devices are:","actuators",["reservoirs","filters","dryers"],"Actuators produce motion.")
H("830.d.6.K",4,"Which pair of actuators produces linear and rotary motion, in that order?","a cylinder and a motor",["a motor and a cylinder","a filter and a gauge","a strainer and a pump"],"Cylinder linear, motor rotary.")
H("830.d.6.L",3,"A cylinder that uses fluid to push the rod out and a spring to bring it back is a:","single-acting cylinder",["double-acting cylinder","rotary motor","pump"],"Single-acting uses spring return.")
H("830.d.6.L",4,"A telescoping cylinder is chosen when a:","long stroke is needed from a short retracted length",["short stroke only","no rod","zero pressure"],"Telescoping cylinders extend in stages.")
H("830.d.6.M",3,"A cylinder with ports at both ends so that fluid pushes the piston out and also brings it back is:","double-acting",["single-acting","spring-return","gravity-return"],"Both directions are powered.")
H("830.d.6.M",4,"On the retract stroke of a double-acting cylinder, the oil is fed to the:","rod end",["cap end","tank only","gauge port"],"Retraction uses the rod-end port.")
H("830.d.6.N",3,"A flow control valve in a circuit lets an operator slow a cylinder to a crawl so that a part can be pressed gently. This shows the valve:","regulates actuator speed",["raises pressure","filters oil","stores energy"],"Flow valves control speed.")
H("830.d.6.N",4,"A meter-out flow control placed on the cylinder's outlet helps prevent:","a load from running away",["pressure from rising","filters from clogging","tanks from filling"],"Meter-out gives control against overrunning loads.")
H("830.d.6.O",3,"A part that lets oil pass freely in one direction but blocks reverse flow, holding a load in place when the pump stops, is a:","check valve",["relief valve","flow meter","gauge"],"Check valves hold load.")
H("830.d.6.O",4,"A pilot-operated check valve is used to:","hold a cylinder in position until pilot pressure lets it release",["keep oil hot","filter oil","change the oil color"],"Pilot checks release on demand.")
H("830.d.6.P",3,"A hydraulic accumulator stores pressurized fluid and releases it when needed, which can:","smooth out pressure spikes and supply extra flow",["raise noise","stop all oil","lower gauge numbers only"],"Accumulators store energy.")
H("830.d.6.P",4,"If the pump shuts off, an accumulator on the circuit can:","still supply fluid briefly to finish a cycle",["add pressure instantly forever","remove oil","damage the tank"],"Stored fluid provides emergency power.")
H("830.d.7.A",3,"A designer sketches a circuit in which a pump feeds a fixed-direction motor through a flow control valve, with a return line to the tank. This is a design for a:","circuit with a unidirectional motor",["circuit with two cylinders only","vacuum circuit","lighting circuit"],"Unidirectional motor circuit.")
H("830.d.7.A",4,"In a design with a unidirectional motor, the motor outlet line should connect to the:","reservoir",["pump inlet gauge","relief valve cap","tool tray"],"Return flow goes to tank.")
H("830.d.7.B",3,"A designer wants a conveyor motor to spin both ways. The directional valve should have positions that send oil to either motor port, which makes it a:","circuit with a bi-directional motor",["unidirectional circuit","manual lift","pneumatic dryer"],"Reversing motor circuit.")
H("830.d.7.B",4,"To stop a bi-directional motor from free-spinning when the valve is centered, the designer can pick a center position that:","blocks both motor ports",["opens both ports to tank","removes the pump","drains the tank"],"Blocked center holds motor.")
H("830.d.7.C",3,"A designer plans a circuit where one pump powers a lift cylinder and a clamp cylinder using two directional valves. This is a circuit with:","multiple cylinders",["a single motor","no actuators","a vacuum generator"],"Two actuators on one pump.")
H("830.d.7.C",4,"When two cylinders are plumbed in parallel to one pump, the cylinder with the lighter load will usually move:","first",["last","never","backward"],"Oil takes the path of least resistance.")
H("830.d.7.D",3,"The designer adds an adjustable valve in the line to a cylinder so that the rod can be slowed during a delicate press. This is a circuit with a:","flow control valve",["pressure gauge only","new tank","bigger motor"],"Flow control sets speed.")
H("830.d.7.D",4,"A designer who wants the rod to extend slowly but retract quickly can place a flow control valve with a built-in check so that:","free flow goes one way and metered flow goes the other",["no flow goes either way","pressure disappears","flow only goes backward"],"Check bypasses the meter.")
H("830.d.7.E",3,"A designer adds a part that blocks reverse flow so a lifted load does not sink when the pump stops. This design incorporates a:","check valve",["relief valve alone","flow meter","tank breather"],"Check valve holds load.")
H("830.d.7.E",4,"In a circuit with a check valve, the arrow on its schematic symbol points toward the direction of:","free flow",["blocked flow","the pump's motor","the filter"],"Arrow shows free flow direction.")
H("830.d.7.F",3,"A designer uses a four-way, three-position directional valve to extend, hold and retract a cylinder. This shows:","a basic circuit using a directional control valve configuration",["a vacuum generator","a gauge test","a filter change"],"4/3 valves give three positions.")
H("830.d.7.F",4,"A 4-way valve gets its name because it has:","four working ports",["four tanks","four motors","four gauges"],"Ports P, T, A, B.")
H("830.d.7.G",3,"A designer chooses a lever, a push button and an electric solenoid as the ways to shift directional valves. These are:","operators for directional control",["kinds of filters","kinds of fluids","kinds of tanks"],"Operators shift valves.")
H("830.d.7.G",4,"Which operator would let a computer shift a valve without a person touching it?","a solenoid",["a hand lever","a foot pedal","a spring"],"Solenoids are electric operators.")
H("830.d.7.H",3,"A designer wants a clamp cylinder to hold a part before a drill cylinder moves. A sequence valve opens only after the first cylinder reaches a set pressure, so it:","operates multiple actuators in order",["stops all actuators","lowers tank level","raises noise only"],"Sequence valves order motion.")
H("830.d.7.H",4,"If the clamp cylinder in a sequence circuit does not reach the sequence valve's set pressure, the second cylinder will:","not move",["move first","move backward","explode"],"The valve stays closed below set pressure.")
H("830.d.7.I",3,"A designer needs a branch that feeds a small clamp at 500 psi from a 2,000 psi main line. The device is a:","pressure reducing valve",["sequence valve","tank strainer","accumulator"],"Reducing valves cut branch pressure.")
H("830.d.7.I",4,"The branch circuit downstream of a reducing valve sees pressure that is:","at or below the valve's set value",["always at main pressure","higher than the main","zero in all cases"],"Downstream is limited.")
H("830.d.8.A",3,"A technician joins hydraulic lines using threaded fittings, flared tube fittings and quick-disconnect couplers. These are:","methods of connecting fluid power circuits",["methods for painting hoses","methods for storing oil","methods for cooling tanks"],"Common connection methods.")
H("830.d.8.A",4,"Wrapping the male threads of a tapered pipe fitting with the right sealant tape helps to:","prevent leaks at the joint",["reduce flow","raise noise","warm the oil"],"Sealant fills thread gaps.")
H("830.d.8.B",3,"Before cutting into a pressurized hydraulic line for a new installation, a technician must first:","lock out the power and relieve all pressure",["open the line live","spray the fitting","remove the gauge"],"De-energize and depressurize.")
H("830.d.8.B",4,"During installation, wearing safety glasses and gloves and keeping hands away from pinholes helps protect against:","fluid injection and splashes",["static noise","paint chips only","color fading"],"PPE protects from fluid hazards.")
H("830.d.8.C",3,"After building the plan for a drive circuit, a technician mounts the pump, the directional valve and a fixed-direction motor and plumbs them with hoses. She is installing a:","circuit with a unidirectional motor",["vacuum circuit","paint circuit","lighting circuit"],"Install per design.")
H("830.d.8.C",4,"After installing the motor circuit, the first thing to verify before full speed is:","correct rotation and no leaks at low pressure",["full-pressure operation immediately","color of hoses","tank paint"],"Check at low pressure first.")
H("830.d.8.D",3,"A technician installs a reversible hydraulic motor with a directional valve and connects the valve's two work ports to each motor port. She is installing a:","circuit with a bi-directional motor",["unidirectional circuit","vacuum circuit","manual jack"],"Two work ports to two motor ports.")
H("830.d.8.D",4,"After wiring a bi-directional motor circuit, shifting the valve one way should turn the motor one direction and the other way should:","turn it the opposite direction",["do nothing","stop the pump","vent the tank"],"Reversing check.")
H("830.d.8.E",3,"A technician pipes two cylinders to the same pump through two directional valves. She is installing a circuit with:","multiple cylinders",["a single motor","a vacuum generator","no actuators"],"Two actuators installed.")
H("830.d.8.E",4,"When bleeding air from a newly installed cylinder, the technician should:","cycle the cylinder slowly several times at low pressure",["run it at full speed dry","remove the rod","close all ports"],"Slow cycling purges air.")
H("830.d.8.F",3,"A technician installs a needle valve in the line to slow a cylinder to a crawl. This is a circuit with a:","flow control valve",["pressure gauge only","new reservoir","vacuum pad"],"Flow valve installed.")
H("830.d.8.F",4,"To verify that the installed flow control valve works, the technician adjusts it and observes the rod:","change speed as the setting is changed",["never move","stay at one speed","move backward"],"Speed responds to adjustment.")
H("830.d.8.G",3,"A technician installs a one-way valve in a lift circuit so that the load will not drop when the pump shuts off. This is installing:","a check valve",["a heat exchanger","a vacuum pump","a muffler"],"Check valve installed.")
H("830.d.8.G",4,"When mounting a check valve, the flow arrow on the body must point:","in the direction of free flow",["against free flow","at the tank wall","at the floor"],"Orientation matters.")
H("830.d.8.H",3,"A technician fits a directional control valve with a mounting plate, O-rings and bolts and connects the A and B ports to a cylinder. She is installing:","a basic circuit using a directional control valve",["a vacuum circuit","a fuel line","a wiring harness"],"Installing a basic DCV circuit.")
H("830.d.8.H",4,"When bolting a subplate-mounted valve to the manifold, the technician makes sure:","the O-rings are seated and the bolts are torqued evenly",["the O-rings are left out","the bolts are loose","the ports are blocked"],"Proper seating prevents leaks.")
H("830.d.8.I",3,"A technician installs a hand lever on one valve, a push button on another and a solenoid on a third. She is installing:","operators for directional control",["filters for oil","gauges for pressure","meters for flow"],"Operators shift valves.")
H("830.d.8.I",4,"After installing a solenoid operator, the technician must also:","connect it to the correct voltage supply safely",["leave it unwired","spray it with water","remove the coil"],"Match voltage.")
H("830.d.8.J",3,"A technician turns the knob on an air regulator until the downstream gauge shows 90 psi to match the system requirement. She is:","adjusting a pneumatic regulator to a defined system pressure",["changing a bearing","draining a tank","painting a hose"],"Adjust to specified pressure.")
H("830.d.8.J",4,"To set a regulator accurately, the technician should turn the adjusting knob while watching the:","downstream gauge",["tank paint","pump housing","supply tag"],"Downstream gauge shows set pressure.")
H("830.d.8.K",3,"With the system running, a technician adjusts the power unit's relief valve to open at 1,500 psi as the specification requires. She is:","adjusting a hydraulic relief valve to a defined system pressure",["changing a hose","filling a tank","testing a filter"],"Adjust relief to spec.")
H("830.d.8.K",4,"The safe way to adjust a relief valve is to:","dead-head the system with a gauge installed and turn the screw slowly",["remove the gauge","run it with the pump off","use the highest setting first"],"Slowly adjust and watch the gauge.")
H("830.d.8.L",3,"A technician plumbs a sequence valve between two cylinders so that the second begins moving after the first completes its stroke. She is:","installing a sequence valve to operate actuators in order",["removing a reservoir","testing a seal","draining oil"],"Sequence valve install.")
H("830.d.8.L",4,"After installing a sequence valve, the technician sets its pressure slightly above:","the pressure needed to complete the first cylinder's motion",["zero","the tank vacuum","the ambient temperature"],"Set above first-stage pressure.")
H("830.d.8.M",3,"A technician fits a pressure reducing valve on a branch line so a small clamp sees less pressure than the main circuit. She is:","installing a pressure reducing valve in a branch circuit",["installing a pump","installing a dryer","installing a tank"],"Reducing valve install.")
H("830.d.8.M",4,"After installation, the technician confirms the reducing valve by checking that the branch gauge reads:","the lower set pressure while the main gauge reads higher",["the same as the main","zero always","a negative value"],"Branch below main.")
H("830.d.9.A",3,"A maintenance planner reviews service records showing that filters on a hydraulic press clog every 600 hours. She sets a filter change at 500 hours. This is developing a:","preventive maintenance schedule from service data",["sales forecast","payroll plan","parking plan"],"Use history to schedule PM.")
H("830.d.9.A",4,"A preventive maintenance schedule differs from fixing parts only after failure because it:","performs service at planned intervals before breakdowns",["waits for breakdowns","skips inspection","avoids records"],"PM is proactive.")
H("830.d.9.B",3,"Repair logs show that a pump motor bearing fails after roughly 9,000 hours, so a technician plans to replace it at 8,000. This is using repair data for:","predictive maintenance",["reactive repair only","price checks","tool storage"],"Predict failures from data.")
H("830.d.9.B",4,"Which data best supports a predictive maintenance decision on a hydraulic pump?","trends in vibration, temperature and past failure hours",["paint color","operator's lunch time","warehouse size"],"Condition data predicts failure.")
H("830.d.9.C",3,"During a walk-around, a technician spots a weeping fitting, a swollen hose and a dented cylinder rod. She is inspecting components for:","signs of malfunction such as leaks, wear and damage",["marketing ideas","pay stubs","label colors"],"Look for failure signs.")
H("830.d.9.C",4,"A cylinder rod with scratches that catch a fingernail should be flagged because it can:","cut the rod seal and cause leaks",["improve sealing","cool the oil","reduce friction"],"Scored rods damage seals.")
H("830.d.9.D",3,"A technician draws a sample of oil that looks milky. This suggests the fluid is contaminated with:","water",["extra additives","fresh oil","paint"],"Milky oil signals water or air.")
H("830.d.9.D",4,"Oil that smells burnt and looks dark and thin is a sign of:","viscosity breakdown from overheating",["fresh fluid","a new filter","a clean tank"],"Heat degrades oil.")
H("830.d.9.E",3,"After shutting down and relieving pressure, a technician unscrews the old filter, wipes the mount, lightly oils the new gasket and spins the new filter on by hand. She is:","changing a filter in a fluid power system",["draining a tank","testing a gauge","bleeding a cylinder"],"Filter change steps.")
H("830.d.9.E",4,"Before removing a pressure filter, the technician must:","lock out and relieve system pressure",["run the pump hot","open the relief valve in operation","skip the lockout"],"Depressurize first.")
H("830.d.9.F",3,"A technician pumps the old oil from the reservoir into a drum, wipes out the sludge, refills with the specified fluid and cycles the system. She is:","draining and replacing hydraulic fluid",["changing a belt","painting the tank","testing a regulator"],"Fluid change steps.")
H("830.d.9.F",4,"Used hydraulic fluid should be:","collected and disposed of through approved recycling",["poured on the ground","poured in a drain","burned in the lot"],"Dispose properly.")
H("830.d.10.A",3,"A compressed air line runs through a narrowed throat so that air speeds up and creates a low-pressure zone that pulls on a suction cup. This describes a:","venturi vacuum application",["hydraulic accumulator","gear pump","diaphragm"],"Venturi uses speed to create vacuum.")
H("830.d.10.A",4,"The Bernoulli effect used in a venturi means that when air speed in the throat rises, the pressure there:","drops",["rises","stays equal","doubles"],"Faster flow, lower pressure.")
H("830.d.10.B",3,"A technician attaches a gauge to a vacuum port and reads 20 inches of mercury. This gauge shows:","how far below atmospheric pressure the system is",["the tank level","the oil temperature","the motor speed"],"Vacuum gauges read below atmospheric.")
H("830.d.10.B",4,"A higher inches-of-mercury reading on a vacuum gauge means:","a stronger vacuum",["a weaker vacuum","higher air pressure","no vacuum"],"Greater vacuum, larger number.")
H("830.d.10.C",3,"A technician connects a U-shaped tube partly filled with liquid to measure small pressure differences. This device is a:","manometer",["tachometer","dial caliper","torque wrench"],"Manometers measure pressure by liquid height.")
H("830.d.10.C",4,"If the liquid column in a manometer is higher on one side by 6 inches, the pressure difference is read as:","6 inches of that liquid",["6 pounds","6 volts","6 revolutions"],"Height difference gives the pressure.")
H("830.d.10.D",3,"A technician plumbs shop air to a small unit and turns on the supply until a suction cup holds a plate. She is:","connecting and operating a vacuum generator",["changing a filter","bleeding a cylinder","charging an accumulator"],"Vacuum generator operation.")
H("830.d.10.D",4,"If the suction cup will not hold a plate, a first check on the vacuum generator should be:","supply air pressure and leaks at the cup",["tank paint","gauge color","tool brand"],"Inspect supply and seal.")
H("830.d.10.E",3,"A vacuum generator has no moving parts and creates vacuum by sending compressed air through an ejector nozzle. Its function is to:","produce a vacuum from compressed air",["store oil","filter water","pump fluid"],"Ejectors create vacuum.")
H("830.d.10.E",4,"A benefit of an air-driven vacuum generator over an electric vacuum pump is that it:","has no moving parts and responds quickly",["needs oil changes","needs a motor","uses no air"],"Simple and fast.")
H("830.d.10.F",3,"A technician tees a venturi into an air line so that air flowing through it will pull a vacuum at a side port. She is:","connecting a venturi to a pneumatic system",["draining a tank","adjusting a relief valve","painting a manifold"],"Venturi hookup.")
H("830.d.10.F",4,"For a venturi to work properly, the air supply should be:","clean, dry and at the pressure the unit is rated for",["wet and dirty","unregulated and varied","absent"],"Quality supply needed.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_122.jsonl"))
